//! The slugger against the real uslug@1.0.4 (with unorm@1.6.0, as Wiki.js
//! 2.5.314 pins them) and Wiki.js's own `h-`/dedupe step:
//! `fixtures/uslug-differential.json`, generated by
//! `tools/gen-uslug-differential.js` from those exact npm packages. The oracle
//! (557 real headings) cannot tell uslug from a simpler slugger; these rows
//! can: compatibility characters, every category-table edge, every code point
//! unorm normalises, the Unicode-version drift, every combining mark and every
//! canonical composite newer than unorm's data, whitespace classes, non-BMP
//! text, random and long strings.

use std::collections::BTreeMap;

use rubrica_render::slug::{uslug, Slugs};
use serde::Deserialize;

#[derive(Deserialize)]
struct Fixture {
    exhaustive: Exhaustive,
    uslug: String,
    unorm: String,
    row_count: usize,
    rows: Vec<Row>,
    pages: Vec<PageRow>,
}

#[derive(Deserialize)]
struct Exhaustive {
    code_points: usize,
    sha256: String,
}

#[derive(Deserialize)]
struct Row {
    group: String,
    input: String,
    slug: String,
    id: String,
}

#[derive(Deserialize)]
struct PageRow {
    texts: Vec<String>,
    ids: Vec<String>,
}

fn load() -> Fixture {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/uslug-differential.json"
    );
    let bytes = std::fs::read(path).unwrap_or_else(|e| panic!("read {path}: {e}"));
    serde_json::from_slice(&bytes).unwrap_or_else(|e| panic!("parse {path}: {e}"))
}

#[test]
fn every_row_matches_the_real_uslug_and_wikijs_heading_id() {
    let fx = load();
    assert_eq!((fx.uslug.as_str(), fx.unorm.as_str()), ("1.0.4", "1.6.0"));
    assert_eq!(fx.rows.len(), fx.row_count);
    assert!(fx.rows.len() > 10_000, "fixture is suspiciously small");
    let mut per_group: BTreeMap<&str, (usize, usize)> = BTreeMap::new();
    let mut examples = Vec::new();
    for row in &fx.rows {
        let slug = uslug(&row.input);
        let id = Slugs::new().heading_id(&row.input).id;
        let entry = per_group.entry(&row.group).or_default();
        entry.0 += 1;
        if slug != row.slug || id != row.id {
            entry.1 += 1;
            if examples.len() < 40 {
                examples.push(format!(
                    "  [{}] {:?}: uslug {:?} / id {:?}, rubrica {:?} / {:?}",
                    row.group, row.input, row.slug, row.id, slug, id
                ));
            }
        }
    }
    let failed: usize = per_group.values().map(|g| g.1).sum();
    let summary = per_group
        .iter()
        .map(|(g, (n, bad))| format!("  {g}: {bad} of {n} differ"))
        .collect::<Vec<_>>()
        .join("\n");
    assert_eq!(
        failed,
        0,
        "{failed}/{} rows differ from uslug@1.0.4:\n{summary}\nfirst differences:\n{}",
        fx.rows.len(),
        examples.join("\n")
    );
    eprintln!(
        "uslug_differential: {}/{} rows match",
        fx.rows.len(),
        fx.rows.len()
    );
}

#[test]
fn every_page_sequence_dedupes_like_wikijs() {
    let fx = load();
    assert!(!fx.pages.is_empty());
    let mut bad = Vec::new();
    for page in &fx.pages {
        let mut slugs = Slugs::new();
        let got: Vec<String> = page.texts.iter().map(|t| slugs.heading_id(t).id).collect();
        if got != page.ids {
            bad.push(format!(
                "  {:?}: wikijs {:?}, rubrica {:?}",
                page.texts, page.ids, got
            ));
        }
    }
    assert!(
        bad.is_empty(),
        "{}/{} pages differ:\n{}",
        bad.len(),
        fx.pages.len(),
        bad.join("\n")
    );
}

/// Every code point (surrogates excepted) in five contexts, compared as one
/// SHA-256 over the same lines the generator hashed, so the whole of Unicode
/// is checked without a fixture of tens of megabytes. The third and fourth
/// contexts put the code point between a base and a mark that composes with
/// it, so one that unorm and the crate block or reorder differently shows; the
/// fifth puts U+0307 after it, so one the crate composes with a following mark
/// and unorm does not (U+105D2, U+105DA) shows. A mismatch cannot say where:
/// rerun the generator with its lines written out and diff them against
/// these.
#[test]
fn every_code_point_in_five_contexts_matches_uslug_by_digest() {
    use sha2::{Digest, Sha256};
    use std::fmt::Write as _;
    let fx = load();
    let mut hash = Sha256::new();
    let mut count = 0usize;
    let mut line = String::new();
    for c in (0..=0x10FFFFu32).filter_map(char::from_u32) {
        line.clear();
        let a = uslug(&format!("a{c}b"));
        let b = uslug(&format!("{c}\u{301} X"));
        let d = uslug(&format!("e{c}\u{301}"));
        let e = uslug(&format!("e{c}\u{323}"));
        let f = uslug(&format!("x{c}\u{307}"));
        writeln!(line, "{:x}\t{a}\t{b}\t{d}\t{e}\t{f}", u32::from(c)).expect("write to a String");
        hash.update(line.as_bytes());
        count += 1;
    }
    let digest: String = hash
        .finalize()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect();
    assert_eq!(count, fx.exhaustive.code_points);
    assert_eq!(
        digest, fx.exhaustive.sha256,
        "uslug over all {count} code points differs from uslug@1.0.4"
    );
}
